  const view=document.getElementById('satView');if(view)view.innerHTML='<div class="geo-flight"><div class="flight-grid"></div><div class="flight-scan"></div><div class="flight-ring ring-a"></div><div class="flight-ring ring-b"></div><div class="flight-reticle"><i></i><i></i><i></i><i></i></div><div class="flight-copy"><span>URBANCOOL AI · ORBITAL NAVIGATION</span><b>LOCKING ON</b><small>'+s+' · '+c+'</small><em>CALIBRATING SATELLITE SURFACE · 100 ZONES</em></div><div class="flight-coords">TARGET · '+s.toUpperCase()+' · '+c.toUpperCase()+'</div></div>';
