    if(view)view.innerHTML=`<div class="grid cols"><div class="panel"><h2>${c} · 100-zone thermal surface</h2><div class="desc">Landsat LST · 30 m source product · zone statistics computed from the selected scene</div><div class="mapwrap"><div id="satMap" class="map"></div><div class="heatlegend"><div class="small">SATELLITE LST</div><div class="legendgrad"></div><div class="legendlabels"><span>Cool</span><span>Warm</span><span>Critical</span></div></div></div></div><div class="panel"><h2>Scene intelligence</h2><div class="metricrow"><span>Acquisition</span><b>${x.source.acquired?new Date(x.source.acquired).toLocaleDateString():'—'}</b></div><div class="metricrow"><span>Mean LST</span><b>${x.stats.avgLST==null?'—':fmt(x.stats.avgLST)+'°C'}</b></div><div class="metricrow"><span>Hotspot zones</span><b>${x.stats.hotspots}/${x.city.zoneCount}</b></div><div class="metricrow"><span>Mean NDVI</span><b>${x.stats.avgNDVI==null?'—':fmt(x.stats.avgNDVI,2)}</b></div><div class="metricrow"><span>Mean NDBI</span><b>${x.stats.avgNDBI==null?'—':fmt(x.stats.avgNDBI,2)}</b></div><div class="alert success"><b>REAL DATA</b><div class="small">USGS / NASA Landsat Collection 2 Level-2 · no dummy zone values.</div></div></div></div><div class="panel" style="margin-top:14px"><h2>Selected zone</h2><div class="desc">Click any of the 100 zones to inspect the satellite-derived values.</div><div id="satZoneDetail"></div></div>`;
