  const out=document.getElementById('optout');
  if(!selected||!Number.isFinite(selected.lst)||!Number.isFinite(selected.ndvi)||!Number.isFinite(selected.ndbi)){out.innerHTML='<div class="alert"><b>Optimization unavailable</b><div class="small">Select a zone with valid observed Landsat LST, NDVI and NDBI values.</div></div>';return}
  out.innerHTML='<div class="loading" style="min-height:180px"><div class="loader"></div><span>ANALYZING → SIMULATING → OPTIMIZING…</span></div>';
  const r=await fetch(API+'/optimize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({zone:selected.id,budget,point:selected,cityMeanLST:state.satellite.stats.avgLST,hotspotScore:selected.hotspotScore})});
  const x=await r.json();
  if(!r.ok){out.innerHTML='<div class="alert"><b>Optimization unavailable</b><div class="small">'+(x.error||'Unknown error')+'</div></div>';return}
  const topZones=pts.filter(p=>Number.isFinite(p.lst)&&p.hotspotScore!=null).sort((a,b)=>b.hotspotScore-a.hotspotScore).slice(0,8);
  const siteResults=await Promise.all(topZones.map(async p=>{const rr=await fetch(API+'/optimize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({zone:p.id,budget,point:p,cityMeanLST:state.satellite.stats.avgLST,hotspotScore:p.hotspotScore})});return rr.ok?await rr.json():null}));
  const sites=siteResults.filter(Boolean).map(z=>({...z.best,hotspotScore:topZones.find(p=>p.id===z.zone)?.hotspotScore||0}));
  const meanCooling=sites.length?sites.reduce((a,s)=>a+s.cooling,0)/sites.length:0;
  const exposureIndex=sites.length?sites.reduce((a,s)=>a+(s.cooling*(1+s.hotspotScore/100)),0):0;
  const ranked=x.ranked||[];
  const maxBar=Math.max(...ranked.map(z=>z.cooling),.1);
  out.innerHTML=`<div class="grid cols"><div class="panel"><div class="eyebrow">${state.geo.state.toUpperCase()} · ${state.geo.city.toUpperCase()} · SELECTED ZONE ${selected.id}</div><h2>${x.best.intervention}</h2><div class="small">Optimizer compares all four intervention families for this exact observed zone. Results are model-estimated scenarios, not measured cooling.</div><div class="result cool">-${fmt(x.best.cooling)}°C</div><div class="small">estimated cooling · post LST ${fmt(x.best.after)}°C</div><div class="metricrow"><span>Intensity</span><b>${x.best.intensity}%</b></div><div class="metricrow"><span>Cost</span><b>₹${fmt(x.best.cost,2)}L</b></div><div class="metricrow"><span>Optimization score</span><b>${fmt(x.best.valueScore,3)}</b></div></div><div class="panel"><div class="eyebrow">CITY-WIDE CANDIDATE SITES</div><div class="metricrow"><span>Mean estimated ΔLST</span><b>${fmt(meanCooling)}°C</b></div><div class="metricrow"><span>Sites selected</span><b>${sites.length}</b></div><div class="metricrow"><span>Priority exposure avoided</span><b>${fmt(exposureIndex,1)} index</b></div><div class="small">Exposure is shown as a normalized decision-support index because a population raster is not part of the current satellite pipeline.</div></div></div><div class="panel" style="margin-top:14px"><h2>Optimized Cooling Interventions</h2><div class="desc">Reference-style intervention map: zone LST is the background; marker size represents estimated ΔLST and marker label identifies the selected intervention.</div><div class="mapwrap"><div id="optMap" class="map"></div></div></div><div class="panel" style="margin-top:14px"><h2>Selected interventions · ranked</h2><table class="table"><tr><th>Rank</th><th>Type</th><th>Intensity</th><th>ΔLST (°C)</th><th>Cost</th><th>Score</th></tr>${ranked.slice(0,12).map((z,i)=>'<tr><td>'+(i+1)+'</td><td>'+z.intervention+'</td><td>'+z.intensity+'%</td><td class="cool">-'+fmt(z.cooling)+'</td><td>₹'+fmt(z.cost,2)+'L</td><td>'+fmt(z.valueScore,3)+'</td></tr>').join('')}</table></div><div class="panel" style="margin-top:14px"><h2>Cooling benefit by intervention candidate</h2>${ranked.slice(0,12).map((z,i)=>'<div class="feature"><div class="feature-head"><span>'+(i+1)+'. '+z.intervention+' · '+z.intensity+'%</span><span>-'+fmt(z.cooling)+'°C</span></div><div class="bar"><i style="width:'+Math.max(4,(z.cooling/maxBar)*100)+'%"></i></div></div>').join('')}</div>`;
