async function loadRecommendationCity(s,c){
  const status=document.getElementById('recStatus'),view=document.getElementById('recView');
  if(status)status.textContent='CONNECTING · satellite catalog → zone analytics → priority explanation';
  if(view)view.innerHTML='<div class="geo-flight"><div class="flight-grid"></div><div class="flight-scan"></div><div class="flight-ring ring-a"></div><div class="flight-ring ring-b"></div><div class="flight-reticle"><i></i><i></i><i></i><i></i></div><div class="flight-copy"><span>URBANCOOL AI · PRIORITY ENGINE</span><b>ANALYZING CITY</b><small>'+s+' · '+c+'</small><em>CALCULATING THERMAL · BUILT-UP · VEGETATION SIGNALS</em></div></div>';
  try{
    const r=await fetch(API+'/satellite?'+new URLSearchParams({state:s,city:c})),x=await r.json();if(!r.ok)throw new Error(x.error||'Satellite source unavailable');
    state.geo={state:s,city:c};state.satellite=x;
    if(status)status.textContent='LIVE SATELLITE · '+(x.source.acquired||'latest available scene')+' · '+x.source.sceneId;
    renderRecommendationData(x);
  }catch(e){if(status)status.textContent='SATELLITE ERROR · '+e.message;if(view)view.innerHTML='<div class="panel alert"><b>Live priority source unavailable</b><div class="small">'+e.message+'</div></div>'}
}
function recommendationAction(p){
  const c=p.driverContributions||{};
  if((c.vegetation||0)>=Math.max(c.thermal||0,c.builtup||0))return 'Tree canopy expansion';
  if((c.builtup||0)>=Math.max(c.thermal||0,c.vegetation||0))return 'Cool / reflective roofs';
  return 'Pavement albedo modification';
}
function renderRecommendationData(x){
  const pts=x.points.filter(p=>Number.isFinite(p.hotspotScore)).sort((a,b)=>b.hotspotScore-a.hotspotScore),view=document.getElementById('recView');
  if(!view)return;
  const top=pts.slice(0,10),valid=pts.length;
  view.innerHTML=`<div class="grid cols recommendation-priority-grid"><div class="panel recommendation-map-panel"><h2>${x.city.city} · 100-zone priority map</h2><div class="desc">Priority score = 45% thermal intensity + 30% built-up intensity + 25% vegetation deficit, normalized against this city's valid zones.</div><div class="mapwrap recommendation-mapwrap"><div id="recMap" class="map"></div></div></div><div class="panel"><h2>Priority queue</h2><div class="desc">${valid} zones with valid satellite-derived analytics · highest priority first</div>${top.map((p,i)=>'<div class="metricrow priority-item" style="cursor:pointer" data-zone="'+p.id+'"><span><b>P'+(i+1)+' · Zone '+p.id+'</b><div class="small">'+p.priority+' · score '+fmt(p.hotspotScore,1)+'/100 · '+recommendationAction(p)+'</div><div class="small">'+(p.priorityReasons||[]).slice(0,3).join(' · ')+'</div></span><b class="heattext">'+fmt(p.lst)+'°C</b></div>').join('')}</div></div><div class="panel" style="margin-top:14px"><h2>Why is this zone a priority?</h2><div class="desc">Select a zone on the map or priority queue. Reasons below are calculated from the current city's live satellite distribution, not a fixed text label.</div><div id="recZoneDetail"></div></div>`;
  document.querySelectorAll('.priority-item').forEach(el=>el.onclick=()=>{const p=pts.find(q=>q.id===Number(el.dataset.zone));state.selected=p.id;showRecommendationZone(p)});
  setTimeout(()=>drawRecommendationMap(x,pts),80);
}
function recommendationNarrative(p){const c=p.driverContributions||{},a=recommendationAction(p),d=(c.thermal||0)>=Math.max(c.builtup||0,c.vegetation||0)?'thermal intensity':(c.builtup||0)>=Math.max(c.thermal||0,c.vegetation||0)?'built-up intensity':'vegetation deficit';const why=a==='Tree canopy expansion'?'It directly addresses vegetation deficit through shade and evaporative cooling potential.':a==='Cool / reflective roofs'?'It directly targets heat absorption across the existing built surface without requiring major land acquisition.':'It directly targets heat stored and absorbed by hard urban surfaces within the existing street network.';return 'For Zone '+p.id+', '+a+' is recommended as the first intervention because the observed satellite evidence points most strongly to '+d+' as the dominant local contributor. The zone records an observed Landsat surface temperature of '+fmt(p.lst)+'°C, which is '+(p.lstAnomaly>=0?'+':'')+fmt(p.lstAnomaly)+'°C relative to the selected city mean. Its NDVI is '+fmt(p.ndvi,2)+', while its NDBI is '+fmt(p.ndbi,2)+'. These measurements are evaluated together: the hotspot framework uses 45% thermal intensity, 30% built-up intensity and 25% vegetation deficit, with each component normalized against the selected city’s valid zones. The resulting hotspot score of '+fmt(p.hotspotScore,1)+'/100 and classification of '+p.priority+' therefore describe the zone’s relative position within the city rather than a universal heat probability. '+why+' The recommendation is deliberately tied to the zone’s observed characteristics rather than being a fixed city-wide label. It is also checked against the optimization layer, which evaluates all four intervention families across multiple intensities under budget and intervention-specific feasibility constraints. This comparison matters because the most obvious intervention is not always the most resource-efficient option. A high-cost intervention with limited feasible coverage may be less attractive than a lower-cost action that can address a larger share of the heat-generating surface. The simulator can then test the selected intervention at a chosen intensity and budget, showing modeled before temperature, estimated cooling, modeled after temperature, treated coverage and estimated cost. These outputs are decision-support estimates, not measured field outcomes, and should be validated with local implementation studies before deployment at scale. Practical implementation should also consider site surveys, land ownership, maintenance requirements, local building and street conditions, water availability where relevant, and post-intervention monitoring. A combined strategy may ultimately be stronger than a single intervention, but this recommendation identifies the most defensible first planning action from the current evidence. In short, Zone '+p.id+' is prioritized because its spatial signals indicate a specific heat pattern, and '+a+' is selected because it directly targets the dominant driver while remaining testable through the project’s simulation and optimization framework.'}
function addRecommendationPanel(p){const el=document.getElementById('recZoneDetail');if(!el||document.getElementById('recNarrative'))return;el.insertAdjacentHTML('beforeend','<div id="recNarrative" class="recommendation-narrative"><div class="small">WHY THIS IS THE RECOMMENDED FIRST ACTION</div><p>'+recommendationNarrative(p)+'</p><button class="primary" onclick="state.page=\'reports\';render()">DOWNLOAD FULL ZONE REPORT</button></div>')}
function showRecommendationZone(p){
  const el=document.getElementById('recZoneDetail');if(!el)return;setTimeout(()=>addRecommendationPanel(p),0);
  const c=p.driverContributions||{},pc=p.driverPercentiles||{};
  el.innerHTML='<div class="zone-intel-head"><div><div class="small">ZONE</div><b>'+p.id+'</b></div><div><div class="small">PRIORITY SCORE</div><b class="heattext">'+fmt(p.hotspotScore,1)+'/100</b></div><div><div class="small">CLASS</div><b>'+p.priority+'</b></div></div><div class="grid" style="grid-template-columns:repeat(4,1fr);margin-top:14px"><div><div class="small">LST</div><b>'+fmt(p.lst)+'°C</b></div><div><div class="small">ΔLST VS CITY</div><b>'+(p.lstAnomaly>=0?'+':'')+fmt(p.lstAnomaly)+'°C</b></div><div><div class="small">NDVI</div><b>'+fmt(p.ndvi,2)+'</b></div><div><div class="small">NDBI</div><b>'+fmt(p.ndbi,2)+'</b></div></div><div class="zone-reason"><div class="small">LIVE REASONS</div>'+((p.priorityReasons||[]).map((r,i)=>'<div class="metricrow"><span><b>'+(i+1)+'.</b> '+r+'</span></div>').join('')||'<div class="small">Combined driver signal.</div>')+'<div class="metricrow"><span>Thermal contribution · '+pc.thermal+'th percentile</span><b>'+c.thermal+'%</b></div><div class="metricrow"><span>Built-up contribution · '+pc.builtup+'th percentile</span><b>'+c.builtup+'%</b></div><div class="metricrow"><span>Vegetation deficit contribution · '+pc.vegetation+'th percentile</span><b>'+c.vegetation+'%</b></div><div class="alert success"><b>Suggested response</b><div class="small">'+recommendationAction(p)+' · selected from the dominant local driver; intervention cooling remains model-estimated in the Optimization/Simulator tabs.</div></div></div>';
}
function drawRecommendationMap(x,pts){
  if(state.map){state.map.remove();state.map=null}
  const map=L.map('recMap',{zoomControl:true}).setView(x.city.center,11);state.map=map;
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);
  const vals=pts.map(p=>p.hotspotScore),min=Math.min(...vals),max=Math.max(...vals),dx=(x.city.bbox[2]-x.city.bbox[0])/10,dy=(x.city.bbox[3]-x.city.bbox[1])/10;
  pts.forEach(p=>{const t=(p.hotspotScore-min)/(max-min||1),col=priorityColor(t),b=L.rectangle([[p.lat-dy/2,p.lon-dx/2],[p.lat+dy/2,p.lon+dx/2]],{color:col,weight:1,fillColor:col,fillOpacity:.64}).addTo(map);b.bindTooltip('Zone '+p.id+' · '+p.priority+' · '+fmt(p.hotspotScore,1)+'/100',{className:'zone-tip'});b.on('click',()=>{state.selected=p.id;showRecommendationZone(p)})});
  map.flyTo(x.city.center,11,{duration:2.4,easeLinearity:.2});
  showRecommendationZone(pts.find(p=>p.id===state.selected)||pts[0]);
}
function reportsPage(){setContent('<div class="panel location-panel"><div class="eyebrow">RESEARCH EXPORT</div><h2>Complete zone research report</h2><div class="desc">Generate a PDF containing the selected zone’s observed satellite data, hotspot scale, heat drivers, prediction context, simulation and optimization results, risk classification, priority score, intervention recommendation and methodology disclosures.</div><div class="selector-row"><label>State / Region<select id="repState"></select></label><label>City<select id="repCity"></select></label><label>Zone<select id="repZone"></select></label></div><div class="sat-status" id="repStatus">Select a location and zone.</div><button class="primary" id="downloadReport" style="max-width:360px">DOWNLOAD COMPLETE PDF REPORT</button><div class="small" style="margin-top:12px">The report is generated from the selected live satellite scene. Model-estimated simulation/optimization outputs are explicitly labelled as estimates.</div></div><div class="panel" style="margin-top:14px"><h2>What the report contains</h2><div class="grid cols"><div><div class="metricrow"><span>Observed satellite inputs</span><b>LST · NDVI · NDBI</b></div><div class="metricrow"><span>Heat assessment</span><b>Hotspot · risk · priority</b></div><div class="metricrow"><span>Driver analysis</span><b>Thermal · built-up · vegetation</b></div><div class="metricrow"><span>Prediction context</span><b>Model metrics + baseline</b></div></div><div><div class="metricrow"><span>Cooling simulation</span><b>Before / after · cost</b></div><div class="metricrow"><span>Optimization</span><b>All four intervention families</b></div><div class="metricrow"><span>Recommendation</span><b>Zone-specific rationale</b></div><div class="metricrow"><span>Methodology</span><b>Sources + caveats</b></div></div></div></div>');const st=document.getElementById('repState'),ct=document.getElementById('repCity'),zn=document.getElementById('repZone'),status=document.getElementById('repStatus');st.innerHTML=Object.keys(GEO_CITIES).map(s=>'<option>'+s+'</option>').join('');st.value=state.geo.state;function fillCities(){ct.innerHTML=GEO_CITIES[st.value].map(c=>'<option>'+c+'</option>').join('');ct.value=st.value===state.geo.state?state.geo.city:GEO_CITIES[st.value][0]}function fillZones(){const pts=state.satellite?.points||[];zn.innerHTML=pts.map(p=>'<option value="'+p.id+'">Zone '+p.id+(Number.isFinite(p.lst)?' · '+fmt(p.lst)+'°C':' · NoData')+'</option>').join('');if(state.satellite?.points?.some(p=>Number(p.id)===Number(state.selected)))zn.value=String(state.selected);status.textContent=state.satellite?'LIVE SATELLITE · '+state.geo.state+' · '+state.geo.city+' · '+pts.length+' zones loaded':'Load a city to populate zones.'}async function loadRepCity(){status.textContent='CONNECTING · loading live satellite zones…';try{const r=await fetch(API+'/satellite?'+new URLSearchParams({state:st.value,city:ct.value}));const x=await r.json();if(!r.ok)throw Error(x.error||'Satellite source unavailable');state.geo={state:st.value,city:ct.value};state.satellite=x;const valid=x.points.find(p=>Number.isFinite(p.lst)&&Number.isFinite(p.ndvi)&&Number.isFinite(p.ndbi));state.selected=valid?.id||x.points[0]?.id||1;fillZones()}catch(e){state.satellite=null;zn.innerHTML='<option>Satellite unavailable</option>';status.textContent='SATELLITE ERROR · '+e.message}}fillCities();st.onchange=async()=>{fillCities();await loadRepCity()};ct.onchange=loadRepCity;if(state.satellite?.city?.city===state.geo.city)fillZones();else loadRepCity();zn.onchange=e=>{state.selected=Number(e.target.value);status.textContent='SELECTED · '+state.geo.city+' · Zone '+state.selected};document.getElementById('downloadReport').onclick=async()=>{const zone=zn.value,p=state.satellite?.points?.find(q=>Number(q.id)===Number(zone));if(!zone||!p)return;status.textContent='GENERATING PDF · compiling satellite, drivers, simulation, optimization and recommendation…';try{const sr=await fetch(API+'/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({zone:p.id,point:p,cityMeanLST:state.satellite.stats.avgLST,intervention:'Tree canopy expansion',intensity:25,budget:25})}),sim=await sr.json();const or=await fetch(API+'/optimize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({zone:p.id,point:p,cityMeanLST:state.satellite.stats.avgLST,hotspotScore:p.hotspotScore,budget:25})}),opt=await or.json();const c=p.driverContributions||{},action=(c.vegetation||0)>=Math.max(c.thermal||0,c.builtup||0)?'Tree canopy expansion':(c.builtup||0)>=Math.max(c.thermal||0,c.vegetation||0)?'Cool / reflective roofs':'Pavement albedo modification';const payload={state:st.value,city:ct.value,zone:Number(zone),point:p,source:state.satellite.source,sim,opt,action,recommendation:recommendationNarrative(p)};const r=await fetch(API+'/report',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){const e=await r.json().catch(()=>({}));throw Error(e.error||'PDF generation failed')}const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='UrbanCool-AI-'+ct.value+'-Zone-'+zone+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);status.textContent='PDF READY · complete zone report downloaded.'}catch(e){status.textContent='REPORT ERROR · '+e.message}}}function faqPage(){const faqs=[['What is UrbanCool AI?','UrbanCool AI is a geospatial climate-intelligence decision system that detects urban heat hotspots, explains their local drivers, evaluates cooling interventions and ranks actions under practical constraints.'],['What satellite data is used?','Heat Intelligence uses the latest available Landsat Collection 2 Level-2 surface-temperature scene for the selected city when a usable scene is available. NDVI and NDBI are derived from the same scene’s surface-reflectance bands.'],['How is the hotspot score calculated?','For valid zones, the relative city hotspot index combines 45% thermal intensity, 30% built-up intensity and 25% vegetation deficit. Percentiles are computed against the selected city’s valid zones, so the score is a relative city index, not a probability.'],['Why can a zone show NoData?','Cloud cover, raster validity or missing band statistics can make a zone unusable. UrbanCool AI deliberately keeps NoData rather than silently replacing it with synthetic values.'],['Is the cooling result measured?','No. Simulator and optimization cooling values are model-estimated scenarios derived from observed LST, NDVI and NDBI. They are not claimed to be measured post-intervention temperatures.'],['What does AI Prediction show?','The current interface preserves the observed satellite baseline and model reference metrics. It does not silently substitute a dashboard demo prediction for a spatially trained prediction output.'],['How does Optimization choose an intervention?','It evaluates all four intervention families across multiple intensities, applies budget and intervention-specific feasibility constraints, then ranks feasible scenarios using estimated cooling and priority-adjusted value.'],['What does the PDF report contain?','The report packages the selected zone’s observed satellite metrics, hotspot score, risk and priority, driver contributions, prediction context, intervention simulations, optimization candidates, recommendation rationale, sources and scientific caveats.'],['Can the AI assistant answer questions about a selected zone?','Yes. When a satellite zone is loaded, the assistant receives the selected zone’s current observed metrics and can explain what they mean, why the zone is prioritized, how the score was calculated and what the intervention results represent.']];setContent('<div class="faq-list">'+faqs.map((f,i)=>'<details class="panel faq-item" '+(i===0?'open':'')+'><summary>'+f[0]+'</summary><div class="small">'+f[1]+'</div></details>').join('')+'</div>')}function dataPage(d){setContent(`<div class="grid cols"><div class="panel"><h2>Data provenance</h2><table class="table"><tr><th>Source</th><th>Status</th><th>Role</th></tr>${d.sources.map(s=>'<tr><td>'+s.name+'</td><td><span class="pill">'+s.status+'</span></td><td>'+s.role+'</td></tr>').join('')}</table></div><div class="panel"><h2>Model architecture</h2><div class="code">Environmental features\n        ↓\nEnsemble regression model\n        ↓\nPredicted LST\n        ↓\nPhysics-aware plausibility constraints\n        ↓\nScenario simulation\n        ↓\nConstrained optimization</div><p class="small">Heat Intelligence satellite layers are sourced from live Landsat Collection 2 Level-2 scenes when available. The overview dashboard remains a deterministic demonstration layer. Intervention cooling is model-estimated from observed zone LST/NDVI/NDBI and is not presented as a measured outcome.</p></div></div><div class="panel" style="margin-top:14px"><h2>Data pipeline</h2><div class="statusbar" style="font-size:12px">SATELLITE → WEATHER → URBAN MORPHOLOGY → FEATURE ENGINEERING → DRIVER ANALYSIS → AI/ML → PHYSICS CONSTRAINT → SIMULATION → OPTIMIZATION → RECOMMENDATION</div></div>`)}function about(){setContent(`<div class="panel" style="max-width:900px"><div class="eyebrow">CAPSTONE PROJECT</div><h2 style="font-size:24px;margin-top:8px">Optimizing Urban Heat Mitigation and Cooling Strategies via Artificial Intelligence and Machine Learning</h2><p class="desc">A geospatial, physics-informed AI/ML framework for urban heat stress detection and cooling-intervention optimization.</p><div class="grid cols"><div><h2>Problem</h2><p class="small">Urban heat is spatially uneven. The same city can contain highly exposed built-up hotspots beside cooler vegetated areas.</p><h2>Objective</h2><p class="small">Detect hotspots, explain their drivers, predict heat intensity, simulate interventions and optimize where limited resources should be deployed.</p></div><div><h2>Methodology</h2><div class="code">Data Acquisition → Preprocessing → Driver Analysis → Physics-aware ML → Scenario Simulation → Optimization → Decision Support</div></div></div><div class="alert" style="margin-top:20px"><b>Scientific honesty</b><div class="small">Observed, predicted, simulated and optimized quantities are explicitly separated in the interface. Demonstration spatial data is labeled as model-derived/demo data.</div></div></div>`)}function drawMap(d,mode='heat'){if(state.map){state.map.remove();state.map=null}const map=L.map('map',{zoomControl:true}).setView([19.075,72.875],11);state.map=map;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);const vals=d.points.map(p=>mode==='priority'?p.priorityScore:p.lst),min=Math.min(...vals),max=Math.max(...vals);d.points.forEach(p=>{let v=mode==='priority'?p.priorityScore:p.lst;const t=(v-min)/(max-min||1);const col=mode==='priority'?priorityColor(t):heatColor(t);const b=L.rectangle([[p.lat-.007,p.lon-.007],[p.lat+.007,p.lon+.007]],{color:col,weight:1,fillColor:col,fillOpacity:.62});b.addTo(map);b.bindTooltip('Zone '+p.id+' · '+(mode==='priority'?'Priority '+p.priority:p.lst.toFixed(1)+'°C'),{className:'zone-tip'});b.on('click',()=>{state.selected=p.id;if(document.getElementById('zoneDetail'))document.getElementById('zoneDetail').innerHTML=zoneDetail(p);else {state.page='drivers';render()}})});if(document.getElementById('zoneDetail'))document.getElementById('zoneDetail').innerHTML=zoneDetail(d.points.find(p=>p.id===state.selected)||d.points[0])}function heatColor(t){const stops=['#2b8cbe','#7bc96f','#ffd166','#ff8c42','#e34a4a'];const i=Math.min(stops.length-1,Math.floor(t*(stops.length-1)));return stops[i]}function priorityColor(t){return t>.75?'#ff5f56':t>.5?'#ffb454':t>.25?'#ffd166':'#62d69a'}load();